import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises'
import { dirname, join, resolve, sep } from 'node:path'
import type { Storage, StoredFile } from './storage.js'

const KEY_PATTERN =
  /^[a-z][a-z0-9_]*\/[a-f0-9]{16}\/[a-z][a-z0-9_]*\/[A-Za-z0-9_-]+\.[A-Za-z0-9]{1,8}$/

interface FileMeta {
  contentType: string
  filename: string
}

/**
 * Filesystem backend. Keys are generated by the upload route, never by the
 * client, and are validated again here so a bad key cannot escape the root.
 */
export class LocalStorage implements Storage {
  private readonly root: string

  constructor(dir: string) {
    this.root = resolve(dir)
  }

  async put(key: string, data: Buffer, contentType: string, filename: string): Promise<void> {
    const path = this.pathFor(key)
    await mkdir(dirname(path), { recursive: true })
    const meta: FileMeta = { contentType, filename }
    await writeFile(path, data)
    await writeFile(`${path}.meta.json`, JSON.stringify(meta), 'utf8')
  }

  async get(key: string): Promise<StoredFile | null> {
    const path = this.pathFor(key)
    try {
      const [data, rawMeta] = await Promise.all([
        readFile(path),
        readFile(`${path}.meta.json`, 'utf8'),
      ])
      const meta = JSON.parse(rawMeta) as FileMeta
      return { data, contentType: meta.contentType, filename: meta.filename }
    } catch {
      return null
    }
  }

  async delete(key: string): Promise<void> {
    const path = this.pathFor(key)
    await rm(path, { force: true })
    await rm(`${path}.meta.json`, { force: true })
  }

  async list(): Promise<string[]> {
    const keys: string[] = []

    const walk = async (dir: string, prefix: string): Promise<void> => {
      let entries
      try {
        entries = await readdir(dir, { withFileTypes: true })
      } catch {
        return
      }

      for (const entry of entries) {
        if (entry.name.endsWith('.meta.json')) continue
        if (entry.isDirectory()) {
          await walk(join(dir, entry.name), `${prefix}${entry.name}/`)
          continue
        }
        keys.push(`${prefix}${entry.name}`)
      }
    }

    await walk(this.root, '')
    return keys
  }

  private pathFor(key: string): string {
    if (!KEY_PATTERN.test(key)) throw new Error(`Invalid storage key "${key}"`)
    const path = resolve(join(this.root, key))
    if (!path.startsWith(this.root + sep)) throw new Error('Storage key escapes the root')
    return path
  }
}
